Bash(node -e "
const { buildSessionsWithTRIMP, estimateVO2maxFromRun } = require\('./calc'\);
const { loadData } = require\('./dataLoader'\);
const { getDb } = require\('./db'\);

const data = loadData\(\);
const { fc_repos, fc_max } = data.athlete;
const db = getDb\(\);
const dbLogs = db.prepare\('SELECT date, sport, distance_km, dplus_m, dplus_corrected, duration_min, fc_moy, extra_sessions_json FROM daily_logs ORDER BY date ASC'\).all\(\);
const sessions = buildSessionsWithTRIMP\(data.activities, dbLogs, fc_repos, fc_max\);

// Show top 10 VO2max estimates
const estimates = sessions
  .slice\(-50\)
  .map\(s => \({ 
    date: s.date, 
    km: s.km || s.distance_km, 
    dur: s.duration_min,
    hr: s.fc_moy,
    est: estimateVO2maxFromRun\(s.distance_km, s.duration_min, s.dplus_m, s.fc_moy, fc_repos, fc_max\)
  }\)\)
  .filter\(e => e.est\)
  .sort\(\(a,b\) => b.est - a.est\)
  .slice\(0, 10\);
console.log\('Top 10 VO2max estimates:'\);
estimates.forEach\(e => console.log\(JSON.stringify\(e\)\)\);

// Hill score analysis
const today = new Date\(\);
const cutoff = new Date\(today\); cutoff.setDate\(cutoff.getDate\(\) - 90\);
const hillSessions = sessions.filter\(s => new Date\(s.date\) >= cutoff && s.dplus_m > 0 && s.distance_km > 0 && \(s.dplus_m / s.distance_km\) >= 10\);
console.log\('\\nHill sessions \(90d\):', hillSessions.length\);
const totalRaw = hillSessions.reduce\(\(sum, s\) => sum + s.dplus_m, 0\);
const totalDecayed = hillSessions.reduce\(\(sum, s\) => {
  const daysAgo = \(today - new Date\(s.date\)\) / 86400000;
  return sum + s.dplus_m * Math.exp\(-daysAgo / 45\);
}, 0\);
console.log\('Total D+ \(raw\):', Math.round\(totalRaw\), 'm, decayed:', Math.round\(totalDecayed\)\);
console.log\('Max single session D+:', Math.max\(...hillSessions.map\(s => s.dplus_m\)\)\);
")

Bash(node -e "
const { buildSessionsWithTRIMP, estimateVO2maxFromRun } = require\('./calc'\);
const { loadData } = require\('./dataLoader'\);
const { getDb } = require\('./db'\);

const data = loadData\(\);
const { fc_repos, fc_max } = data.athlete; // 48, 187

// Test with higher HRR threshold and running economy correction
// At HRR threshold = 0.65: min HR = 48 + 0.65*\(187-48\) = 138
console.log\('HRR 0.65 → min HR:', 48 + 0.65*\(187-48\)\);

const db = getDb\(\);
const dbLogs = db.prepare\('SELECT date, sport, distance_km, dplus_m, dplus_corrected, duration_min, fc_moy, extra_sessions_json FROM daily_logs ORDER BY date ASC'\).all\(\);
const sessions = buildSessionsWithTRIMP\(data.activities, dbLogs, fc_repos, fc_max\);

// Simulate stricter HRR filter
const estimates_strict = sessions
  .slice\(-100\)
  .map\(s => {
    if \(!s.distance_km || !s.duration_min || !s.fc_moy || s.duration_min < 20\) return null;
    const speed_m_min = \(s.distance_km * 1000\) / s.duration_min;
    const grade = \(s.dplus_m || 0\) / \(s.distance_km * 1000\);
    const vo2_running = speed_m_min * 0.2 + speed_m_min * grade * 0.9 + 3.5;
    const hrr = \(s.fc_moy - fc_repos\) / \(fc_max - fc_repos\);
    if \(hrr < 0.65 || hrr > 0.95\) return null;
    const est = vo2_running / hrr;
    if \(est < 30 || est > 90\) return null;
    return { date: s.date, hr: s.fc_moy, hrr: Math.round\(hrr*100\)/100, est: Math.round\(est*10\)/10 };
  }\)
  .filter\(e => e\)
  .sort\(\(a,b\) => b.est - a.est\)
  .slice\(0, 10\);

console.log\('Top estimates with HRR >= 0.65:'\);
estimates_strict.forEach\(e => console.log\(JSON.stringify\(e\)\)\);
")

Bash(node -e "
const { buildSessionsWithTRIMP } = require\('./calc'\);
const { loadData } = require\('./dataLoader'\);
const { getDb } = require\('./db'\);

const data = loadData\(\);
const { fc_repos, fc_max } = data.athlete;
const db = getDb\(\);
const dbLogs = db.prepare\('SELECT date, sport, distance_km, dplus_m, dplus_corrected, duration_min, fc_moy, extra_sessions_json FROM daily_logs ORDER BY date ASC'\).all\(\);
const sessions = buildSessionsWithTRIMP\(data.activities, dbLogs, fc_repos, fc_max\);

const today = new Date\(\);
const cutoff = new Date\(today\); cutoff.setDate\(cutoff.getDate\(\) - 90\);
const hillSessions = sessions.filter\(s => new Date\(s.date\) >= cutoff && s.dplus_m > 0 && s.distance_km > 0 && \(s.dplus_m / s.distance_km\) >= 10\);

const endSessions = hillSessions.filter\(s => \(s.dplus_m / s.distance_km\) < 50\);
const strSessions = hillSessions.filter\(s => \(s.dplus_m / s.distance_km\) >= 50\);

const decayFn = \(s\) => { const d = \(today - new Date\(s.date\)\)/86400000; return s.dplus_m * Math.exp\(-d/45\); };

const endDecayed = endSessions.reduce\(\(sum,s\) => sum + decayFn\(s\), 0\);
const strDecayed = strSessions.reduce\(\(sum,s\) => sum + decayFn\(s\), 0\);
const totalDecayed = hillSessions.reduce\(\(sum,s\) => sum + decayFn\(s\), 0\);

console.log\('Endurance sessions:', endSessions.length, 'decayed D+:', Math.round\(endDecayed\)\);
console.log\('Strength sessions:', strSessions.length, 'decayed D+:', Math.round\(strDecayed\)\);
console.log\('Total decayed:', Math.round\(totalDecayed\)\);
console.log\('Target scores: overall=72, endurance=71, strength=43'\);
// REF needed: totalDecayed/REF × 100 = 72 → REF = totalDecayed/0.72
console.log\('REF_OVERALL should be:', Math.round\(totalDecayed/0.72\)\);
console.log\('REF_END should be:', Math.round\(endDecayed/0.71\)\);
console.log\('REF_STR should be:', Math.round\(strDecayed/0.43\)\);

// Also Endurance score calibration
const esLast = data.endurance_score?.at\(-1\)?.es; // 8452
// with vo2=59.4: vo2Component = 59.4/75 * 10000 = 7920
// need total to be 8452. 
// Current: es = vo2 * 0.5 + longTerm * 0.3 + shortTerm * 0.1 + longRun * 0.1
// 7920 * 0.5 = 3960. Need remaining 4492 from load components.
console.log\('\\nEndurance score target:', esLast\);
console.log\('VO2max component \(raw\):', Math.round\(59.4/75 * 10000\)\);
")

Bash(node -e "
const { buildSessionsWithTRIMP } = require\('./calc'\);
const { loadData } = require\('./dataLoader'\);
const { getDb } = require\('./db'\);

const data = loadData\(\);
const { fc_repos, fc_max } = data.athlete;
const db = getDb\(\);
const dbLogs = db.prepare\('SELECT date, sport, distance_km, dplus_m, dplus_corrected, duration_min, fc_moy, extra_sessions_json FROM daily_logs ORDER BY date ASC'\).all\(\);
const sessions = buildSessionsWithTRIMP\(data.activities, dbLogs, fc_repos, fc_max\);

const today = new Date\(\);
const cutoff90 = new Date\(today\); cutoff90.setDate\(cutoff90.getDate\(\) - 90\);
const cutoff14 = new Date\(today\); cutoff14.setDate\(cutoff14.getDate\(\) - 14\);

const longTermSessions = sessions.filter\(s => new Date\(s.date\) >= cutoff90\);
const shortTermSessions = sessions.filter\(s => new Date\(s.date\) >= cutoff14\);

const longTermLoad = longTermSessions.reduce\(\(sum, s\) => {
  const daysAgo = \(today - new Date\(s.date\)\) / 86400000;
  return sum + s.trimp * Math.exp\(-daysAgo / 60\);
}, 0\);

const shortTermLoad = shortTermSessions.reduce\(\(sum, s\) => sum + s.trimp, 0\);
const maxDist = Math.max\(0, ...longTermSessions.map\(s => s.distance_km || 0\)\);

console.log\('Long-term sessions \(90d\):', longTermSessions.length\);
console.log\('Long-term decayed TRIMP:', Math.round\(longTermLoad\)\);
console.log\('Short-term sessions \(14d\):', shortTermSessions.length\);
console.log\('Short-term TRIMP sum:', Math.round\(shortTermLoad\)\);
console.log\('Max distance \(90d\):', maxDist, 'km'\);

// Target es = 8452 with VO2max = 59.4
// score = vo2Comp*0.5 + ltComp*0.3 + stComp*0.1 + lrComp*0.1
// vo2Comp = 59.4/75 * 10000 = 7920
// We need: 7920*0.5 + ltComp*0.3 + stComp*0.1 + lrComp*0.1 = 8452
// → 3960 + ltComp*0.3 + stComp*0.1 + lrComp*0.1 = 8452
// → ltComp*0.3 + stComp*0.1 + lrComp*0.1 = 4492
// If ltComp = stComp = lrComp = X: X * 0.5 = 4492 → X = 8984
// REF for ltComp = 8984: longTermLoad / REF_LT * 10000 = 8984 → REF_LT = longTermLoad/0.8984
console.log\('\\nREF_LONG_TERM should be:', Math.round\(longTermLoad / 0.8984\)\);
console.log\('REF_SHORT_TERM should be:', Math.round\(shortTermLoad / 0.8984\)\);
console.log\('REF_LONG_RUN should be \(km\):', Math.round\(maxDist / 0.8984\)\);
")

