Bash(node -e "
const { loadData } = require\('./backend/dataLoader'\);
const d = loadData\(\);
const zones = d.athlete.zones_karvonen;
const fmt = v => v ? \(Math.floor\(v\)+':'+String\(Math.round\(\(v%1\)*60\)\).padStart\(2,'0'\)\) : 'N/A';

// Better correction: ITRA multiplicative \(100m D+ = 1km flat effort\)
// paceFlat = paceRaw / \(1 + dPerKm/100\)
// Zone-specific filters
const configs = {
  Z1: { maxDplusPerKm: 5, maxKm: 999 },
  Z2: { maxDplusPerKm: 5, maxKm: 999 },
  Z3: { maxDplusPerKm: 8, maxKm: 12 },
  Z4: { maxDplusPerKm: 10, maxKm: 12 },
  Z5: { maxDplusPerKm: 10, maxKm: 10 },
};
const zoneKeys = ['Z1','Z2','Z3','Z4','Z5'];
const buckets = { Z1: [], Z2: [], Z3: [], Z4: [], Z5: [] };

for \(const a of d.activities\) {
  if \(!a.HR_moy || !a.Temps_h || a.is_treadmill || a.Distance_km < 2\) continue;
  const dPerKm = \(a.D_plus_exact || 0\) / a.Distance_km;
  const paceRaw = \(a.Temps_h * 60\) / a.Distance_km;
  const paceFlat = paceRaw / \(1 + dPerKm / 100\); // ITRA correction

  if \(paceFlat < 3 || paceFlat > 12\) continue;

  const z = zoneKeys.find\(z => {
    const [lo, hi] = zones[z];
    return a.HR_moy >= lo && \(a.HR_moy < hi || z === 'Z5'\);
  }\);
  if \(!z\) continue;

  const cfg = configs[z];
  if \(dPerKm > cfg.maxDplusPerKm\) continue;
  if \(a.Distance_km > cfg.maxKm\) continue;

  buckets[z].push\(paceFlat\);
}

for \(const z of zoneKeys\) {
  const paces = buckets[z].sort\(\(a,b\)=>a-b\);
  const lo = paces[Math.floor\(paces.length*0.1\)];
  const hi = paces[Math.floor\(paces.length*0.9\)];
  console.log\(z, 'n='+paces.length, fmt\(lo\)+' – '+fmt\(hi\)+' /km'\);
}
")

