const { loadData } = require\('./dataLoader'\);
const d = loadData\(\);
const zones = d.athlete.zones_karvonen;
const d3m = new Date\(Date.now\(\) - 90*864e5\).toISOString\(\).slice\(0,10\);
const d2y = new Date\(Date.now\(\) - 730*864e5\).toISOString\(\).slice\(0,10\);
const fmt = v => v ? Math.floor\(v\)+':'+String\(Math.round\(\(v%1\)*60\)\).padStart\(2,'0'\) : 'N/A';

// Pour chaque zone : tous les points \(hr_moy, pace_flat\)
// Filtres progressifs par zone
const cfgs = {
  Z1: { from: d3m,          maxDplus: 12, maxKm: 999 },
  Z2: { from: d3m,          maxDplus: 12, maxKm: 999 },
  Z3: { from: d3m,          maxDplus: 12, maxKm: 15  },
  Z4: { from: '2022-01-01', maxDplus: 10, maxKm: 12  },
  Z5: { from: '2022-01-01', maxDplus: 10, maxKm: 10  },
};

const pts = { Z1:[], Z2:[], Z3:[], Z4:[], Z5:[] };
for \(const a of d.activities\) {
  if \(!a.HR_moy || !a.Temps_h || a.is_treadmill || a.Distance_km < 2\) continue;
  const dPerKm = \(a.D_plus_exact||0\)/a.Distance_km;
  const paceFlat = \(a.Temps_h*60\)/a.Distance_km / \(1+dPerKm/100\);
  if \(paceFlat < 3 || paceFlat > 12\) continue;
  for \(const [z,[lo,hi]] of Object.entries\(zones\)\) {
    if \(a.HR_moy >= lo && \(a.HR_moy < hi || z==='Z5'\)\) {
      const cfg = cfgs[z];
      if \(a.Date >= cfg.from && dPerKm <= cfg.maxDplus && a.Distance_km <= cfg.maxKm\)
        pts[z].push\({ hr: a.HR_moy, pace: paceFlat, date: a.Date }\);
      break;
    }
  }
}

// Stats par zone + régression
for \(const [z, arr] of Object.entries\(pts\)\) {
  const paces = arr.map\(p=>p.pace\).sort\(\(a,b\)=>a-b\);
  const hrs   = arr.map\(p=>p.hr\);
  const p10 = paces[Math.floor\(paces.length*0.1\)];
  const p50 = paces[Math.floor\(paces.length*0.5\)];
  const p90 = paces[Math.floor\(paces.length*0.9\)];
  const hrMed = hrs.sort\(\(a,b\)=>a-b\)[Math.floor\(hrs.length/2\)];
  console.log\(z, 'n='+arr.length, 'hr_med='+hrMed, 'p10='+fmt\(p10\), 'p50='+fmt\(p50\), 'p90='+fmt\(p90\)\);
}

// Régression linéaire sur les p10 \(meilleure perf à chaque zone\)
// Points : \(hr_median_zone, p10_pace_zone\) pour Z1 Z2 Z3
const zoneList = ['Z1','Z2','Z3'];
const regPts = zoneList.map\(z => {
  const arr = pts[z];
  const paces = arr.map\(p=>p.pace\).sort\(\(a,b\)=>a-b\);
  const hrs   = arr.map\(p=>p.hr\).sort\(\(a,b\)=>a-b\);
  const p10 = paces[Math.floor\(paces.length*0.1\)];
  const hrMed = hrs[Math.floor\(hrs.length/2\)];
  return { hr: hrMed, pace: p10 };
}\);
console.log\('\\nPoints régression \(z, hr_med, p10_pace\):'\);
zoneList.forEach\(\(z,i\) => console.log\(' ', z, regPts[i].hr, fmt\(regPts[i].pace\)\)\);

// Linear regression: pace = a + b*hr
const n = regPts.length;
const sumX = regPts.reduce\(\(s,p\)=>s+p.hr, 0\);
const sumY = regPts.reduce\(\(s,p\)=>s+p.pace, 0\);
const sumXY = regPts.reduce\(\(s,p\)=>s+p.hr*p.pace, 0\);
const sumX2 = regPts.reduce\(\(s,p\)=>s+p.hr*p.hr, 0\);
const b = \(n*sumXY - sumX*sumY\) / \(n*sumX2 - sumX*sumX\);
const a = \(sumY - b*sumX\) / n;
console.log\('Régression: pace =', a.toFixed\(4\), '+', b.toFixed\(6\), '* hr'\);

// Extrapolation Z4 Z5
const z4bounds = zones.Z4; const z5bounds = zones.Z5;
const hrZ4lo = z4bounds[0], hrZ4hi = z4bounds[1];
const hrZ5lo = z5bounds[0], hrZ5hi = z5bounds[1];
const pZ4lo = a + b*hrZ4lo, pZ4hi = a + b*hrZ4hi;
const pZ5lo = a + b*hrZ5lo, pZ5hi = a + b*hrZ5hi;
console.log\('\\nExtrapolation Z4:', fmt\(pZ4hi\), '–', fmt\(pZ4lo\), '/km', '\('+hrZ4lo+'–'+hrZ4hi+' bpm\)'\);
console.log\('Extrapolation Z5:', fmt\(pZ5hi\), '–', fmt\(pZ5lo\), '/km', '\('+hrZ5lo+'–'+hrZ5hi+' bpm\)'\);
")
